import{H as e,V as t,et as n,j as r}from"./chunks/framework.Dj60FFN6.js";var i=JSON.parse(`{"title":"Il concetto di convessità","description":"","frontmatter":{},"headers":[],"relativePath":"lezioni/f_geometria-del-piano-euclideo/fc/fcc.md","filePath":"lezioni/f_geometria-del-piano-euclideo/fc/fcc.md"}`),a={name:`lezioni/f_geometria-del-piano-euclideo/fc/fcc.md`};function o(r,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[e(`<h1 id="il-concetto-di-convessita" tabindex="-1">Il concetto di convessità <a class="header-anchor" href="#il-concetto-di-convessita" aria-label="Permalink to “Il concetto di convessità”">​</a></h1><p>La nozione di angolo ci permette di introdurre un nuovo concetto: il concetto di convessità. Se consideriamo un angolo e consideriamo il prolungamento dei suoi lati (in viola) abbiamo due possibilità:</p><ul><li>L&#39;angolo non contiene il prolungamento dei suoi lati (a sinistra)</li><li>L&#39;angolo contiene il prolungamento dei suoi lati</li></ul><p>Nel primo caso chiameremo l&#39;angolo convesso e nel secondo lo chiameremo concavo.</p><hr><p>Cerchiamo di estendere la nozione non limitandola al concetto di angolo nel seguente modo:</p><blockquote><p class="text-red">[<strong>Una figura si dice convessa se contiene ogni segmento di cui contenga gli estremi; in caso contrario la figura si dice non convessa.</strong>]</p></blockquote><hr><blockquote><p>Presi comunque due punti nella prima figura, il segmento che li unisce è sempre tutto contenuto. Nella seconda figura, invece, posso trovare almeno due punti tali che il segmento esce dalla figura, allora tale figura la chiameremo non convessa.</p></blockquote>`,9)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};